$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT EmployeeId, FullName, PrimaryRole, SecondaryRole, TeamLeadName FROM Employees WHERE PrimaryRole='VWIC' OR SecondaryRole='VWIC' ORDER BY PrimaryRole, FullName"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] $r[1] $r[2] $r[3] $r[4]}; $conn.Close()
